 let entry=feedback.get(scope);if(!entry){const node=document.createElement('div');node.dataset.uxFeedback='';node.className='ux-error-feedback'+(scope?' ux-modal-error':' ux-page-error');node.setAttribute('role','alert');node.setAttribute('aria-atomic','true');const text=document.createElement('div');text.className='ux-error-text';const close=document.createElement('button');close.type='button';close.className='ux-error-close';close.textContent='×';close.setAttribute('aria-label',T('Dismiss error','오류 알림 닫기'));node.append(text,close);const foot=footer(scope);let dock=null;if(foot){foot.classList.add('ux-has-error');foot.prepend(node);}else if(scope){dock=document.createElement('div');dock.className='ux-error-dock';dock.append(node);scope.append(dock);}else document.body.append(node);entry={node,text,close,footer:foot,dock,rows:[]};feedback.set(scope,entry);close.addEventListener('click',()=>{for(const row of entry.rows){row.dismissed=true;unsuppress(row.node);}remove(scope);});}
