 for(const n of document.querySelectorAll(errors)){if(!validSource(n))continue;const text=n.textContent.replace(/\s+/g,' ').trim();let r=records.get(n);if(!r){r={node:n,text,owner:n.closest(dialogs)||latest,dismissed:false};records.set(n,r);}else if(text!==r.text){r.text=text;r.owner=n.closest(dialogs)||latest;r.dismissed=false;}}
