function viewport(){const vv=window.visualViewport,height=vv?.height||innerHeight,offset=vv?.offsetTop||0,keyboard=Math.max(0,innerHeight-height-offset),nav=document.querySelector('.cmd-sidebar'),rect=nav?.getBoundingClientRect(),bottom=innerWidth<=700&&rect&&rect.height<innerHeight*.35&&rect.bottom>=innerHeight-3?Math.max(0,innerHeight-rect.top):0,root=document.documentElement;const values={'--ux-visual-height':height+'px','--ux-visual-top':offset+'px','--ux-error-bottom':(Math.max(keyboard,bottom)+12)+'px'};for(const [key,value]of Object.entries(values))if(root.style.getPropertyValue(key)!==value)root.style.setProperty(key,value);}
function clearField(field){const state=fieldState.get(field);if(!state)return;state.node.remove();if(state.invalid==null)field.removeAttribute('aria-invalid');else field.setAttribute('aria-invalid',state.invalid);if(state.described==null)field.removeAttribute('aria-describedby');else field.setAttribute('aria-describedby',state.described);fieldState.delete(field);schedule();}
